// Overlap guard for a single operator: one comparison run at a time.
// A leftover 'running' status means a previous run is still going, failed, or was canceled.
// Recovery: stop any active execution of this workflow (Executions list), then open the
// comparison_runs table, set the status cell to 'aborted', then rerun.
const st = $input.first().json;
if (st.status === 'running') {
  throw new Error('A S2 eval run (latest_s2) is marked as still in progress (started ' + (st.started_at || 'unknown') + '). Stop any active execution of this workflow, set the comparison_runs status cell to aborted, then rerun.');
}
return $input.all();

// The status-table nodes above emit the comparison_runs row, not the dataset row.
// Hand the original row back to the chain.
return [{ json: $('When fetching a dataset row').first().json, pairedItem: { item: 0 } }];

// Timestamp just before the model call so the Score node can compute
// client-side wall time for the call - the SAME measurer on both eval workflows,
// which is what makes s1_wall_ms and s2_wall_ms directly comparable.
const start = Date.now();
return $input.all().map((item) => ({ json: { ...item.json, call_start_ms: start } }));

// Same tolerant parser as the System 2 demo workflow: strip fences, slice the
// JSON object out of any surrounding prose, validate the fields, flag failures.
return $input.all().map((item) => {
  const raw = String(item.json.response ?? '').trim();
  const latency_ms = Math.round((item.json.total_duration || 0) / 1e6);
  const output_tokens = item.json.eval_count ?? null;
  let parsed = null;
  let parse_error = null;
  try {
    const cleaned = raw.replace(/```(json)?/gi, '');
    const start = cleaned.indexOf('{');
    const end = cleaned.lastIndexOf('}');
    if (start === -1 || end === -1 || end <= start) throw new Error('no JSON object in response');
    parsed = JSON.parse(cleaned.slice(start, end + 1));
  } catch (e) {
    parse_error = 'parse_failed: ' + e.message;
  }
  let urgent = null, team = null, confidence = null;
  if (parsed) {
    urgent = typeof parsed.urgent === 'number' ? parsed.urgent : null;
    team = ['infra', 'billing', 'sales'].includes(parsed.team) ? parsed.team : null;
    confidence = typeof parsed.confidence === 'number' ? parsed.confidence : null;
    if (urgent === null || team === null) parse_error = 'invalid_fields: ' + raw.slice(0, 120);
  }
  return { json: { urgent, team, confidence, parse_error, output_tokens, latency_ms } };
});

// Score System 2 (general LLM via Ollama) against ground truth, per row.
// Routing rule mirrored from the demo workflows' Route Decision node:
//   confidence < 0.6 -> human_review; urgent >= 0.7 -> page_oncall:<team>; else queue:<team>
// A parse failure is its own route so it can never accidentally match human_review.
// Everything is written as TEXT so a CSV-imported Data Table (all string columns) accepts it.
// Only s2_* columns are written - the expected_* label columns are never touched.
// s2_status makes freshness fail-closed in the table itself: at run start every row is marked
// STALE; as a row completes, its status becomes 'current as of <s2_run_at>'. A row still showing
// STALE means its s2_* values are from a previous run and must not be read as current.
const row = $('When fetching a dataset row').first().json;
const s2 = $('Parse LLM JSON (S2)').first().json;

const CONF_MIN = 0.6, URGENT_MIN = 0.7;
const routeOf = (team, conf, urgentProb) => {
  if (team === null || team === undefined || team === '' || conf === null || conf === undefined) return 'no_answer';
  if (conf < CONF_MIN) return 'human_review';
  if (urgentProb >= URGENT_MIN) return 'page_oncall:' + team;
  return 'queue:' + team;
};

// Two same-boundary latencies (the S1 workflow measures its call the same two ways):
//   s2_wall_ms   = client-side wall time around the HTTP call (identical measurer both systems)
//   s2_server_ms = Ollama's own server-reported total_duration, ns -> ms (load + prompt eval + eval)
const s2_server_ms = s2.latency_ms;
const s2_run_at = new Date().toISOString();
const s2_wall_ms = Date.now() - Number($('Mark Call Start').first().json.call_start_ms || 0);
const s2_route = s2.parse_error ? 'parse_failed' : routeOf(s2.team, s2.confidence, s2.urgent);

const expected_team = String(row.expected_team ?? '').trim();
const expected_urgent = String(row.expected_urgent ?? '').trim() === '1';
const expected_route = String(row.expected_route ?? '').trim();

const flag = (ok) => (ok ? 'correct' : 'WRONG');
const s2_team_correct = expected_team ? flag(!s2.parse_error && s2.team === expected_team) : '';
const s2_urgent_correct = flag(!s2.parse_error && typeof s2.urgent === 'number' && (s2.urgent >= URGENT_MIN) === expected_urgent);
const s2_route_correct = flag(s2_route === expected_route);

const fmt = (v) => (typeof v === 'number' ? String(Math.round(v * 1000) / 1000) : String(v ?? ''));

return [{ json: {
  s2_team: s2.team || '',
  s2_confidence: fmt(s2.confidence),
  s2_urgent: fmt(s2.urgent),
  s2_server_ms: String(s2_server_ms ?? ''),
  s2_wall_ms: String(s2_wall_ms),
  s2_run_at,
  s2_status: 'current as of ' + s2_run_at,
  s2_route,
  s2_parse_error: s2.parse_error || '',
  s2_team_correct,
  s2_urgent_correct,
  s2_route_correct
} }];
